import { useMemo, useState } from "react";
import { HiBanknotes, HiBellAlert, HiBuildingOffice2, HiBuildingStorefront, HiCalendarDays, HiCheckCircle, HiDocumentText, HiHomeModern, HiKey, HiMegaphone, HiPlus, HiQrCode, HiScale, HiTicket, HiUserCircle, HiUsers, HiXMark } from "react-icons/hi2";
import PropertiesLogo from "../components/PropertiesLogo";
import "./community-portal.css";

const initialTickets=[{id:"OT-240381",title:"Fuga debajo del lavabo",status:"En progreso",updated:"Hoy · 14:26"}];
const notices=[{id:"n1",title:"Mantenimiento preventivo del elevador",body:"El elevador estará fuera de servicio el jueves de 10:00 a 13:00.",date:"22 ago",read:false},{id:"n2",title:"Minuta de asamblea disponible",body:"Ya puedes consultar acuerdos y presupuesto aprobado.",date:"18 ago",read:true}];
const initialPasses=[{id:"AC-1849",name:"Mariana Robles + 1",window:"Hoy · 17:30–18:15",status:"Vigente"}];

function CommunityPortal(){
  const [section,setSection]=useState("home");const [role,setRole]=useState("owner");const [paid,setPaid]=useState(false);const [tickets,setTickets]=useState(initialTickets);const [passes,setPasses]=useState(initialPasses);const [reservations,setReservations]=useState([{id:"r1",amenity:"Roof garden",date:"29 ago · 18:00",status:"Confirmada"}]);const [vote,setVote]=useState(null);const [sheet,setSheet]=useState(null);const [draft,setDraft]=useState("");
  const nav=[["home",HiHomeModern,"Mi comunidad"],["charges",HiBanknotes,"Cuotas y pagos"],["notices",HiMegaphone,"Avisos y documentos"],["amenities",HiBuildingStorefront,"Amenidades"],["access",HiKey,"Visitas y paquetes"],["tickets",HiTicket,"Mis tickets"],["votes",HiScale,"Votaciones"]];
  const unread=notices.filter(item=>!item.read).length;
  const title=useMemo(()=>nav.find(([key])=>key===section)?.[2],[section]);
  const addItem=event=>{event.preventDefault();if(!draft.trim())return;if(sheet==="ticket")setTickets(current=>[{id:`OT-${String(Date.now()).slice(-6)}`,title:draft.trim(),status:"Abierto",updated:"Ahora"},...current]);if(sheet==="pass")setPasses(current=>[{id:`AC-${String(Date.now()).slice(-4)}`,name:draft.trim(),window:"Hoy · acceso autorizado",status:"Vigente"},...current]);if(sheet==="reservation")setReservations(current=>[{id:`R-${Date.now()}`,amenity:draft.trim(),date:"Próxima fecha disponible",status:"Confirmada"},...current]);setDraft("");setSheet(null)};
  return <div className="community-portal-shell">
    <aside className="community-portal-nav" aria-label="Navegación del portal"><header><PropertiesLogo/><span>PORTAL COMUNIDAD</span></header><nav>{nav.map(([key,Icon,label])=><button type="button" key={key} className={section===key?"active":""} onClick={()=>setSection(key)}><Icon/><span>{label}</span>{key==="notices"&&unread?<i>{unread}</i>:null}</button>)}</nav><footer><span>MT</span><div><strong>Mariana Torres</strong><small>{role==="owner"?"Propietaria":"Residente"}</small></div><HiUserCircle/></footer></aside>
    <main className="community-portal-main"><header><div><small>Torre Jacarandas · Departamento 201</small><h1>{title}</h1></div><div className="community-role-switch"><button className={role==="owner"?"active":""} onClick={()=>setRole("owner")}>Propietaria</button><button className={role==="resident"?"active":""} onClick={()=>setRole("resident")}>Residente</button></div><button className="community-bell"><HiBellAlert/><i>{unread}</i></button></header>
      <section className="community-unit-banner"><div><span>Tu unidad en la comunidad</span><h2>Departamento 201</h2><p>Comunidad Torre Jacarandas · CDMX</p><div><small>Relación</small><strong>{role==="owner"?"Propietaria principal · Residente":"Residente autorizado"}</strong></div></div><HiBuildingOffice2/><button onClick={()=>setSection("notices")}>Ver reglamento <HiDocumentText/></button></section>
      {section==="home"&&<Home paid={paid} tickets={tickets} reservations={reservations} setSection={setSection} setSheet={setSheet}/>}
      {section==="charges"&&<Charges paid={paid} setPaid={setPaid} role={role}/>}
      {section==="notices"&&<Notices/>}
      {section==="amenities"&&<Amenities reservations={reservations} setSheet={setSheet}/>}
      {section==="access"&&<Access passes={passes} setSheet={setSheet}/>}
      {section==="tickets"&&<Tickets tickets={tickets} setSheet={setSheet}/>}
      {section==="votes"&&<Votes vote={vote} setVote={setVote} role={role}/>}
      <footer>Tu información sólo es visible según tu relación con esta unidad y los permisos de la comunidad.</footer>
    </main>
    {sheet&&<div className="community-sheet-backdrop" onClick={()=>setSheet(null)}><form className="community-sheet" onSubmit={addItem} onClick={e=>e.stopPropagation()}><header><div><small>Nueva acción</small><h2>{sheet==="ticket"?"Crear ticket":sheet==="pass"?"Autorizar acceso":"Reservar amenidad"}</h2></div><button type="button" onClick={()=>setSheet(null)}><HiXMark/></button></header><label>{sheet==="ticket"?"¿Qué necesitas reportar?":sheet==="pass"?"Nombre de la visita, proveedor o entrega":"Amenidad y horario solicitado"}<textarea autoFocus rows="4" value={draft} onChange={e=>setDraft(e.target.value)} required/></label><footer><button type="button" onClick={()=>setSheet(null)}>Cancelar</button><button type="submit">Confirmar</button></footer></form></div>}
  </div>;
}

function Home({paid,tickets,reservations,setSection,setSheet}){return <><section className="community-pulse"><article><HiBanknotes/><div><small>Saldo actual</small><strong>{paid?"$0":"$1,850"}</strong><em>{paid?"Al corriente":"Venció el 10 de agosto"}</em></div></article><article><HiTicket/><div><small>Tickets activos</small><strong>{tickets.length}</strong><em>Seguimiento disponible</em></div></article><article><HiCalendarDays/><div><small>Próxima reserva</small><strong>{reservations[0]?.amenity||"Sin reserva"}</strong><em>{reservations[0]?.date||"Explorar horarios"}</em></div></article></section><section className="community-home-grid"><article className="community-action-card"><span>Lo importante hoy</span><h2>{paid?"Tu cuenta está al corriente.":"Tienes una cuota pendiente."}</h2><p>{paid?"No necesitas realizar ninguna acción de cobranza.":"Cuota ordinaria de agosto · $1,850 MXN."}</p><button onClick={()=>setSection("charges")}>Ver estado de cuenta</button></article><article className="community-shortcuts"><span>Acciones rápidas</span><div><button onClick={()=>setSheet("ticket")}><HiTicket/>Crear ticket</button><button onClick={()=>setSheet("pass")}><HiQrCode/>Autorizar visita</button><button onClick={()=>setSheet("reservation")}><HiBuildingStorefront/>Reservar amenidad</button><button onClick={()=>setSection("votes")}><HiScale/>Participar</button></div></article></section></>}
function Charges({paid,setPaid,role}){return <section className="community-section"><header><div><span>Estado de cuenta</span><h2>Cuotas, pagos y recibos</h2><p>Sólo aparecen cargos relacionados con tu unidad.</p></div>{!paid&&role==="owner"?<button onClick={()=>setPaid(true)}>Registrar pago demo</button>:null}</header><div className="community-balance"><div><small>Saldo</small><strong>{paid?"$0":"$1,850"}</strong><em className={paid?"ok":"due"}>{paid?"Al corriente":"Vencido"}</em></div><div><small>Pagado este año</small><strong>{paid?"$16,650":"$14,800"}</strong><em>8 movimientos</em></div><div><small>Próximo cargo</small><strong>$1,850</strong><em>01 sep 2026</em></div></div><div className="community-list"><article><HiBanknotes/><div><strong>Cuota ordinaria · agosto</strong><small>Vencimiento 10 ago 2026</small></div><b>$1,850</b><i className={paid?"ok":"due"}>{paid?"Pagada":"Pendiente"}</i></article><article><HiCheckCircle/><div><strong>Cuota ordinaria · julio</strong><small>Pagada 04 jul 2026 · SPEI</small></div><b>$1,850</b><i className="ok">Pagada</i></article></div></section>}
function Notices(){return <section className="community-section"><header><div><span>Información oficial</span><h2>Comunicados y documentos</h2><p>Avisos, minutas, reglamentos y archivos compartidos.</p></div></header><div className="community-list">{notices.map(item=><article key={item.id}><HiMegaphone/><div><strong>{item.title}</strong><small>{item.body}</small></div><time>{item.date}</time><i className={item.read?"ok":"new"}>{item.read?"Leído":"Nuevo"}</i></article>)}<article><HiDocumentText/><div><strong>Reglamento de la comunidad</strong><small>PDF · actualizado 03 ene 2026</small></div><button>Consultar</button></article></div></section>}
function Amenities({reservations,setSheet}){return <section className="community-section"><header><div><span>Espacios compartidos</span><h2>Amenidades y reservaciones</h2><p>Consulta reglas y reserva únicamente horarios disponibles.</p></div><button onClick={()=>setSheet("reservation")}><HiPlus/> Nueva reserva</button></header><div className="community-amenities"><article><HiBuildingStorefront/><h3>Roof garden</h3><p>Hasta 24 personas · 10:00–22:00</p><span>Disponible</span></article><article><HiUsers/><h3>Salón de usos múltiples</h3><p>Hasta 40 personas · requiere aprobación</p><span>Disponible</span></article></div><div className="community-list">{reservations.map(item=><article key={item.id}><HiCalendarDays/><div><strong>{item.amenity}</strong><small>{item.date}</small></div><i className="ok">{item.status}</i></article>)}</div></section>}
function Access({passes,setSheet}){return <section className="community-section"><header><div><span>Caseta y recepción</span><h2>Visitas, proveedores y paquetería</h2><p>Comparte sólo lo necesario para autorizar un acceso.</p></div><button onClick={()=>setSheet("pass")}><HiPlus/> Nuevo pase</button></header><div className="community-list">{passes.map(item=><article key={item.id}><HiQrCode/><div><strong>{item.name}</strong><small>{item.id} · {item.window}</small></div><button>Compartir</button><i className="ok">{item.status}</i></article>)}<article><HiKey/><div><strong>Paquete recibido en recepción</strong><small>Mensajería Express · hoy 12:40</small></div><button>Confirmar recepción</button><i className="new">Nuevo</i></article></div></section>}
function Tickets({tickets,setSheet}){return <section className="community-section"><header><div><span>Atención y mantenimiento</span><h2>Mis tickets</h2><p>Crea solicitudes y sigue cada actualización.</p></div><button onClick={()=>setSheet("ticket")}><HiPlus/> Nuevo ticket</button></header><div className="community-list">{tickets.map(item=><article key={item.id}><HiTicket/><div><strong>{item.title}</strong><small>{item.id} · actualizado {item.updated}</small></div><button>Ver seguimiento</button><i className="progress">{item.status}</i></article>)}</div></section>}
function Votes({vote,setVote,role}){return <section className="community-section"><header><div><span>Participación</span><h2>Votaciones y acuerdos</h2><p>{role==="owner"?"Tu relación tiene derecho de voto.":"Puedes consultar; el voto corresponde a la persona propietaria."}</p></div></header><article className="community-vote"><HiScale/><div><small>Abierta hasta 31 ago</small><h3>Renovación de pintura en lobby</h3><p>Aprobación del presupuesto presentado por el comité.</p></div>{vote?<strong>Tu voto: {vote}</strong>:role==="owner"?<footer><button onClick={()=>setVote("Sí")}>Sí</button><button onClick={()=>setVote("No")}>No</button><button onClick={()=>setVote("Abstención")}>Abstención</button></footer>:<i>Consulta</i>}</article></section>}

export default CommunityPortal;
